import flash.display.DisplayObject;
import flash.events.IOErrorEvent;
import flash.events.SecurityErrorEvent;
import flash.text.TextField;
import flash.text.TextFormat;

private var VenworksCUILoader:Loader = null;
private var VenworksCUIBridge:Object = null;
private var VenworksCUIBootstrapDiagnostics:TextField = null;
private var VenworksCUIHudModeVisibility:Array = null;
private var VenworksCUIBootstrapStarted:Boolean = false;
private var VenworksCUIBootstrapDisposed:Boolean = false;

private function startVenworksCUI() : void
{
   if(this.VenworksCUIBootstrapStarted && !this.VenworksCUIBootstrapDisposed)
   {
      return;
   }
   this.VenworksCUIBootstrapStarted = true;
   this.VenworksCUIBootstrapDisposed = false;
   this.removeVenworksCUIDiagnostics();
   try
   {
      this.VenworksCUILoader = new Loader();
      this.VenworksCUILoader.contentLoaderInfo.addEventListener(Event.INIT,this.onVenworksCUIInit,false,0,true);
      this.VenworksCUILoader.contentLoaderInfo.addEventListener(Event.COMPLETE,this.onVenworksCUIComplete,false,0,true);
      this.VenworksCUILoader.contentLoaderInfo.addEventListener(IOErrorEvent.IO_ERROR,this.onVenworksCUIError,false,0,true);
      this.VenworksCUILoader.contentLoaderInfo.addEventListener(SecurityErrorEvent.SECURITY_ERROR,this.onVenworksCUIError,false,0,true);
      addEventListener(Event.REMOVED_FROM_STAGE,this.onVenworksCUIRemoved,false,0,true);
      this.VenworksCUILoader.load(new URLRequest("venworkscui.swf"));
   }
   catch(venworksLoadError:Error)
   {
      this.showVenworksCUIError("CUI-AUX-LOAD",venworksLoadError.toString());
      this.disposeVenworksCUI();
   }
}

private function onVenworksCUIInit(param1:Event) : void
{
   if(this.VenworksCUIBootstrapDisposed || this.VenworksCUILoader == null)
   {
      return;
   }
   try
   {
      this.VenworksCUIBridge = this.VenworksCUILoader.content;
      if(this.VenworksCUIBridge == null || !("initialize" in this.VenworksCUIBridge))
      {
         throw new Error("Auxiliary movie does not expose initialize().");
      }
      this.VenworksCUIBridge["initialize"](this);
      this.reapplyVenworksCUIPlacements();
      if(this.VenworksCUIHudModeVisibility != null)
      {
         this.VenworksCUIBridge["updateVanillaHudModeVisibility"](this.VenworksCUIHudModeVisibility);
      }
      this.removeVenworksCUIDiagnostics();
   }
   catch(venworksInitializeError:Error)
   {
      this.showVenworksCUIError("CUI-AUX-INIT",venworksInitializeError.toString());
      this.disposeVenworksCUI();
   }
}

private function onVenworksCUIComplete(param1:Event) : void
{
   var loadedContent:DisplayObject = null;
   if(this.VenworksCUIBootstrapDisposed || this.VenworksCUILoader == null)
   {
      return;
   }
   this.removeVenworksCUILoadListeners();
   try
   {
      loadedContent = this.VenworksCUILoader.content;
      if(this.VenworksCUIBridge == null || loadedContent == null || loadedContent !== this.VenworksCUIBridge)
      {
         throw new Error("Auxiliary movie completed without its initialized entrypoint.");
      }
      if(loadedContent.parent !== this)
      {
         addChild(loadedContent);
      }
      this.reapplyVenworksCUIPlacements();
      if(this.VenworksCUIHudModeVisibility != null)
      {
         this.VenworksCUIBridge["updateVanillaHudModeVisibility"](this.VenworksCUIHudModeVisibility);
      }
      this.removeVenworksCUIDiagnostics();
   }
   catch(venworksInitializeError:Error)
   {
      this.showVenworksCUIError("CUI-AUX-INIT",venworksInitializeError.toString());
      this.disposeVenworksCUI();
   }
}

private function onVenworksCUIError(param1:Event) : void
{
   this.showVenworksCUIError("CUI-AUX-IO",param1.toString());
   this.disposeVenworksCUI();
}

private function onVenworksCUIRemoved(param1:Event) : void
{
   if(param1.target === this)
   {
      this.disposeVenworksCUI();
   }
}

private function reapplyVenworksCUIPlacements() : void
{
   try
   {
      if(this.VenworksCUIBridge != null && "reapplyVanillaPlacements" in this.VenworksCUIBridge)
      {
         this.VenworksCUIBridge["reapplyVanillaPlacements"]();
      }
   }
   catch(venworksPlacementError:Error)
   {
      this.showVenworksCUIError("CUI-AUX-PLACE",venworksPlacementError.toString());
   }
}

private function updateVenworksCUIHudModeVisibility(param1:Array) : void
{
   this.VenworksCUIHudModeVisibility = param1 == null ? null : param1.concat();
   try
   {
      if(this.VenworksCUIBridge != null && "updateVanillaHudModeVisibility" in this.VenworksCUIBridge)
      {
         this.VenworksCUIBridge["updateVanillaHudModeVisibility"](this.VenworksCUIHudModeVisibility);
      }
   }
   catch(venworksVisibilityError:Error)
   {
      this.showVenworksCUIError("CUI-AUX-MODE",venworksVisibilityError.toString());
   }
}

private function removeVenworksCUILoadListeners() : void
{
   if(this.VenworksCUILoader == null)
   {
      return;
   }
   this.VenworksCUILoader.contentLoaderInfo.removeEventListener(Event.INIT,this.onVenworksCUIInit);
   this.VenworksCUILoader.contentLoaderInfo.removeEventListener(Event.COMPLETE,this.onVenworksCUIComplete);
   this.VenworksCUILoader.contentLoaderInfo.removeEventListener(IOErrorEvent.IO_ERROR,this.onVenworksCUIError);
   this.VenworksCUILoader.contentLoaderInfo.removeEventListener(SecurityErrorEvent.SECURITY_ERROR,this.onVenworksCUIError);
}

private function disposeVenworksCUI() : void
{
   var loadedContent:DisplayObject = null;
   if(this.VenworksCUIBootstrapDisposed)
   {
      return;
   }
   this.VenworksCUIBootstrapDisposed = true;
   removeEventListener(Event.REMOVED_FROM_STAGE,this.onVenworksCUIRemoved);
   this.removeVenworksCUILoadListeners();
   if(this.VenworksCUIBridge != null)
   {
      try
      {
         if("dispose" in this.VenworksCUIBridge)
         {
            this.VenworksCUIBridge["dispose"]();
         }
      }
      catch(venworksDisposeError:Error)
      {
         trace("CUI-AUX-DISPOSE | " + venworksDisposeError.toString());
      }
   }
   if(this.VenworksCUIBridge is DisplayObject)
   {
      loadedContent = this.VenworksCUIBridge as DisplayObject;
      if(loadedContent.parent === this)
      {
         removeChild(loadedContent);
      }
   }
   this.VenworksCUIBridge = null;
   this.VenworksCUIHudModeVisibility = null;
   if(this.VenworksCUILoader != null)
   {
      try
      {
         this.VenworksCUILoader.unload();
      }
      catch(venworksUnloadError:Error)
      {
         trace("CUI-AUX-UNLOAD | " + venworksUnloadError.toString());
      }
   }
   this.VenworksCUILoader = null;
}

private function showVenworksCUIError(param1:String, param2:String) : void
{
   var format:TextFormat = new TextFormat("$MAIN_Font_Bold",18,16777215,true);
   try
   {
      if(this.VenworksCUIBootstrapDiagnostics == null)
      {
         this.VenworksCUIBootstrapDiagnostics = new TextField();
         this.VenworksCUIBootstrapDiagnostics.name = "VenworksCUIBootstrapDiagnostics";
         this.VenworksCUIBootstrapDiagnostics.x = 720;
         this.VenworksCUIBootstrapDiagnostics.y = 96;
         this.VenworksCUIBootstrapDiagnostics.width = 480;
         this.VenworksCUIBootstrapDiagnostics.height = 72;
         this.VenworksCUIBootstrapDiagnostics.background = true;
         this.VenworksCUIBootstrapDiagnostics.backgroundColor = 4194304;
         this.VenworksCUIBootstrapDiagnostics.border = true;
         this.VenworksCUIBootstrapDiagnostics.borderColor = 16711680;
         this.VenworksCUIBootstrapDiagnostics.textColor = 16777215;
         this.VenworksCUIBootstrapDiagnostics.embedFonts = true;
         this.VenworksCUIBootstrapDiagnostics.defaultTextFormat = format;
         this.VenworksCUIBootstrapDiagnostics.multiline = true;
         this.VenworksCUIBootstrapDiagnostics.wordWrap = true;
         this.VenworksCUIBootstrapDiagnostics.selectable = false;
         this.VenworksCUIBootstrapDiagnostics.mouseEnabled = false;
         addChild(this.VenworksCUIBootstrapDiagnostics);
      }
      this.VenworksCUIBootstrapDiagnostics.text = "VENWORKS CUI LOAD ERROR\n" + param1 + " | " + param2;
      this.VenworksCUIBootstrapDiagnostics.setTextFormat(format);
   }
   catch(venworksDiagnosticsError:Error)
   {
      trace(param1 + " | " + param2);
   }
}

private function removeVenworksCUIDiagnostics() : void
{
   if(this.VenworksCUIBootstrapDiagnostics != null && this.VenworksCUIBootstrapDiagnostics.parent === this)
   {
      removeChild(this.VenworksCUIBootstrapDiagnostics);
   }
   this.VenworksCUIBootstrapDiagnostics = null;
}
